function descriptionText(node) {
  if (typeof node === "string") return node;
  if (!node || typeof node !== "object") return "";
  if (node.type === "text") return typeof node.text === "string" ? node.text : "";
  if (node.type === "hardBreak") return "\n";
  const children = Array.isArray(node.content) ? node.content : [];
  return children.map(descriptionText).join(node.type === "doc" ? "\n" : "");
}

function escapeWithin(text, limit) {
  const entities = { "&": "&amp;", "<": "&lt;", ">": "&gt;" };
  let result = "";
  for (const character of text) {
    const escaped = entities[character] ?? character;
    if (result.length + escaped.length > limit - 1) return result + "…";
    result += escaped;
  }
  return result;
}

function prepareMessage({ event, body, chatIds }) {
  let issue = body;
  let kind = event;
  if (event === "jira:issue_created" || event === "jira:issue_updated") {
    issue = body.issue;
    const changes = body.changelog?.items;
    kind =
      event === "jira:issue_created"
        ? "created"
        : Array.isArray(changes) &&
            changes.some(
              (item) => item?.fieldId === "assignee" || item?.field?.toLowerCase() === "assignee",
            )
          ? "change-assignee"
          : "updated";
  }

  const labels = {
    created: "🆕 New",
    updated: "⚠️ Updated",
    "change-assignee": "👩‍💻 Assigned to you",
  };
  const fields = issue?.fields;
  const accountId = fields?.assignee?.accountId;
  if (
    !Object.hasOwn(labels, kind) ||
    typeof issue?.key !== "string" ||
    !issue.key ||
    typeof accountId !== "string" ||
    !Object.hasOwn(chatIds, accountId)
  )
    return { send: false, chatId: null, text: null };

  const chatId = String(chatIds[accountId]);
  if (!/^-?[1-9]\d*$/.test(chatId)) {
    throw new Error("Set a numeric Telegram chat ID for the mapped Jira assignee");
  }

  const label = labels[kind] + " " + escapeWithin(String(fields.issuetype?.name || "issue"), 120);
  const project = escapeWithin(String(fields.project?.name || ""), 180);
  const key = escapeWithin(issue.key, 120);
  const title = escapeWithin(String(fields.summary || ""), 800);
  const created = fields.created;
  const createdValue =
    typeof created === "object" && created !== null ? created.epochMillis : created;
  const date = new Date(createdValue ?? NaN);
  const createdLine = Number.isFinite(date.getTime())
    ? "\nCreated: " + date.toISOString().slice(0, 16).replace("T", " ") + " UTC"
    : "";
  const heading =
    label + "\n\nProject: " + project + "\nKey: " + key + "\nTitle: " + title + "\nDescription: ";
  const description = escapeWithin(
    descriptionText(fields.description),
    4096 - heading.length - createdLine.length,
  );
  return { send: true, chatId, text: heading + description + createdLine };
}

const chatIds = {};
return $input.all().flatMap(({ json }, index) => {
  const event = json.headers?.type;
  if (!["created", "updated", "change-assignee"].includes(event)) return [];
  const { send, chatId, text } = prepareMessage({ event, body: json.body, chatIds });
  return send ? [{ json: { chatId, text }, pairedItem: { item: index } }] : [];
});
